// Generate non_gregorian_data.go: locales whose Intl default calendar is not
// gregory. Formatting dates for these without their calendar would be silent
// wrong output, so the formatter returns a typed error instead.
import { writeFileSync, readdirSync } from 'node:fs';
const dir = 'node_modules/cldr-dates-full/main';
const nonGreg = [];
for (const f of readdirSync(dir)) {
  const loc = f.replace(/_/g, '-');
  try {
    const cal = new Intl.DateTimeFormat(loc).resolvedOptions().calendar;
    if (cal !== 'gregory') nonGreg.push(f.replace(/-/g, '_'));
  } catch {}
}
let src = `// Code generated by testdata/gen/gen-calendar-check.mjs from Node Intl resolvedOptions. DO NOT EDIT.\npackage messageformat\n\n// nonGregorianDefaultLocales: locales whose default calendar is not Gregorian\n// (Intl.DateTimeFormat resolvedOptions().calendar). Date/time formatting for\n// these returns a typed error rather than silently rendering Gregorian dates.\nvar nonGregorianDefaultLocales = map[string]bool{\n`;
for (const l of nonGreg) src += `\t${JSON.stringify(l)}: true,\n`;
src += '}\n';
writeFileSync('../../non_gregorian_data.go', src);
console.log('non-gregorian-default locales:', nonGreg.length, nonGreg.slice(0, 8).join(','));
